package co.edu.uco.seguridad.pdp.authorization.application.usecase.impl;
import co.edu.uco.seguridad.pdp.authorization.application.primaryport.request.ListApplicationSecurityAdministratorsRequest; import co.edu.uco.seguridad.pdp.authorization.application.rule.validator.PrincipalMustBeApplicationAdministratorValidator; import co.edu.uco.seguridad.pdp.authorization.application.usecase.ListApplicationSecurityAdministratorsUseCase; import co.edu.uco.seguridad.pdp.assignments.application.primaryport.request.ListApplicationAssignmentsPageRequest; import co.edu.uco.seguridad.pdp.assignments.application.primaryport.response.AssignmentResponse; import co.edu.uco.seguridad.pdp.assignments.application.usecase.ListApplicationAdministratorsPageUseCase; import co.edu.uco.seguridad.pdp.commons.model.ResultPage; import reactor.core.publisher.Mono;
public final class ListApplicationSecurityAdministratorsUseCaseImpl implements ListApplicationSecurityAdministratorsUseCase {private final PrincipalMustBeApplicationAdministratorValidator gate;private final ListApplicationAdministratorsPageUseCase administrators;public ListApplicationSecurityAdministratorsUseCaseImpl(PrincipalMustBeApplicationAdministratorValidator gate,ListApplicationAdministratorsPageUseCase administrators){this.gate=gate;this.administrators=administrators;}public Mono<ResultPage<AssignmentResponse>> execute(ListApplicationSecurityAdministratorsRequest i){return gate.execute(i.administration()).then(Mono.defer(()->administrators.execute(new ListApplicationAssignmentsPageRequest(i.administration().tenantId(),i.administration().applicationId(),i.window()))));}}
